class PreRestoreState {
  final Set<String> walletIds;
  final Map<String, dynamic> validJSON;

  PreRestoreState(this.walletIds, this.validJSON);
}

String getErrorMessageFromSWBException(Exception e) {
  String errorMessage = e.toString();
  if (e is BadDataLength) {
    errorMessage = e.errMsg();
  } else if (e is BadProtocolVersion) {
    errorMessage = e.errMsg();
  } else if (e is FailedDecryption) {
    errorMessage = e.errMsg();
  } else if (e is BadChecksum) {
    errorMessage = e.errMsg();
  } else if (e is BadAadLength) {
    errorMessage = e.errMsg();
  }
  return errorMessage;
}

/// "2026-10-12_09-05-03": file names then sort by date.
String _backupStamp(DateTime d) {
  String two(int n) => n.toString().padLeft(2, "0");
  return "${d.year}-${two(d.month)}-${two(d.day)}"
      "_${two(d.hour)}-${two(d.minute)}-${two(d.second)}";
}

const _autoBackupPrefix = "${AppConfig.appName}-autobackup-";

String createBackupFilename(String dirPath, DateTime date) =>
    "$dirPath/${AppConfig.appName}-backup-${_backupStamp(date)}.swb";

/// [autoBackupDate] reads the date back to rotate out old auto backups.
String createAutoBackupFilename(String dirPath, DateTime date) =>
    "$dirPath/$_autoBackupPrefix${_backupStamp(date)}.swb";

/// The date of an auto backup file named by [createAutoBackupFilename],
/// or null for any other file.
DateTime? autoBackupDate(String fileName) {
  final m = RegExp(
    "^${RegExp.escape(_autoBackupPrefix)}"
    r"(\d{4})-(\d\d)-(\d\d)_(\d\d)-(\d\d)-(\d\d)\.swb$",
  ).firstMatch(fileName);
  if (m == null) return null;
  final d = [for (var i = 1; i <= 6; i++) int.parse(m.group(i)!)];
  return DateTime(d[0], d[1], d[2], d[3], d[4], d[5]);
}

bool validateFail(
  BuildContext context,
  String pathToSave,
  String passphrase,
  String repeatPassphrase,
) {
  final missing = passwordMissing(passphrase);
  for (final e in [
    [pathToSave.isEmpty, l10n.backupNoDirectory],
    if (!pathToSave.startsWith("content://"))
      [!(Directory(pathToSave).existsSync()), l10n.backupDirectoryMissing],
    [passphrase.isEmpty, l10n.backupPassphraseRequired],
    [missing != null, missing ?? ""],
    [passphrase != repeatPassphrase, l10n.verifyPassphraseMismatch],
  ]) {
    if (e[0] as bool) {
      if (context.mounted) {
        unawaited(
          showFloatingFlushBar(
            type: FlushBarType.warning,
            message: e[1] as String,
            context: context,
          ),
        );
      }
      return true;
    }
  }

  return false;
}

abstract class SWB {
  static Completer<void>? _cancelCompleter;

  static Future<void> cancelRestore() async {
    if (!_shouldCancelRestore) {
      _cancelCompleter = null;
      _cancelCompleter = Completer<void>();
      _shouldCancelRestore = true;
      Logging.instance.d("SWB cancel restore requested");
    } else {
      Logging.instance.d(
        "SWB cancel restore requested while a cancellation request is currently in progress",
      );
    }

    // return completer that will complete on SWBRestoreCancelEventType.completed event
    return _cancelCompleter!.future;
  }

  static bool _shouldCancelRestore = false;

  static bool _checkShouldCancel(
    PreRestoreState? revertToState,
    SecureStorageInterface secureStorageInterface,
  ) {
    if (_shouldCancelRestore) {
      if (revertToState != null) {
        _revert(revertToState, secureStorageInterface);
      } else {
        _cancelCompleter!.complete();
        _shouldCancelRestore = false;
      }

      return true;
    } else {
      return false;
    }
  }

  static Future<String> encryptStackWalletWithPassphrase(
    String passphrase,
    String plaintext,
  ) async {
    final String jsonBackup = plaintext;
    final Uint8List content = Uint8List.fromList(utf8.encode(jsonBackup));
    final Uint8List encryptedContent = await encryptWithPassphrase(
      passphrase,
      content,
    );
    return Format.uint8listToString(encryptedContent);
  }

  static Future<String> encryptStackWalletWithADK(
    String adk,
    String plaintext,
    int adkVersion,
  ) async {
    final String jsonBackup = plaintext;
    final Uint8List content = Uint8List.fromList(utf8.encode(jsonBackup));
    final Uint8List encryptedContent = await encryptWithAdk(
      Format.stringToUint8List(adk),
      content,
      version: adkVersion,
    );
    return Format.uint8listToString(encryptedContent);
  }

  static Future<String?> decryptStackWalletStringWithPassphrase(
    ({String passphrase, String encryptedText}) data,
  ) async {
    try {
      final encryptedBytes = Format.stringToUint8List(data.encryptedText);

      final decryptedContent = await decryptWithPassphrase(
        data.passphrase,
        encryptedBytes,
      );

      final jsonBackup = utf8.decode(decryptedContent);
      return jsonBackup;
    } catch (e, s) {
      Logging.instance.e("$e\n$s", error: e, stackTrace: s);
      return null;
    }
  }

  /// The backup. Every release so far writes all of this, and restoring
  /// needs all of it ([isSwbBackup]). A field added from now on is
  /// optional when restoring, since backups from before it don't have it:
  /// read it only when it's there (`if (prefs['newField'] is bool)`), and
  /// leave it out of [isSwbBackup].
  ///
  /// [secureStorage] parameter exposed for testing purposes
  static Future<Map<String, dynamic>> createStackWalletJSON({
    required SecureStorageInterface secureStorage,
  }) async {
    Logging.instance.d("Starting createStackWalletJSON...");
    final _wallets = Wallets.sharedInstance;
    final Map<String, dynamic> backupJson = {};
    final NodeService nodeService = NodeService(
      secureStorageInterface: secureStorage,
    );

    Logging.instance.d("createStackWalletJSON awaiting DB.instance.mutex...");
    // prevent modification of data
    await DB.instance.mutex.protect(() async {
      Logging.instance.i("...createStackWalletJSON DB.instance.mutex acquired");
      Logging.instance.i("SWB backing up nodes");
      backupJson['nodes'] = nodeService.nodes.map((e) => e.toMap()).toList();

      Logging.instance.d("SWB backing up prefs");

      final Map<String, dynamic> prefs = {};
      final _prefs = Prefs.instance;
      await _prefs.init();
      prefs['currency'] = _prefs.currency;
      prefs['useBiometrics'] = _prefs.useBiometrics;
      prefs['hasPin'] = _prefs.hasPin;
      prefs['language'] = _prefs.language;
      prefs['showFavoriteWallets'] = _prefs.showFavoriteWallets;
      prefs['syncType'] = _prefs.syncType.name;
      prefs['walletIdsSyncOnStartup'] = _prefs.walletIdsSyncOnStartup;
      prefs['showTestNetCoins'] = _prefs.showTestNetCoins;
      prefs['externalCalls'] = _prefs.externalCalls;
      prefs['isAutoBackupEnabled'] = _prefs.isAutoBackupEnabled;
      prefs['autoBackupLocation'] = _prefs.autoBackupLocation;
      prefs['backupFrequencyType'] = _prefs.backupFrequencyType.toString();
      prefs['lastAutoBackup'] = _prefs.lastAutoBackup.toString();
      prefs['enableCoinControl'] = _prefs.enableCoinControl;
      prefs['amountUnits'] = {
        for (final coin in AppConfig.coins)
          coin.identifier: _prefs.amountUnit(coin).name,
      };
      prefs['maxDecimals'] = {
        for (final coin in AppConfig.coins)
          coin.identifier: _prefs.maxDecimals(coin),
      };
      prefs['themeId'] = _prefs.themeId;
      prefs['enableSystemBrightness'] = _prefs.enableSystemBrightness;
      prefs['systemBrightnessLightThemeId'] =
          _prefs.systemBrightnessLightThemeId;
      prefs['systemBrightnessDarkThemeId'] = _prefs.systemBrightnessDarkThemeId;
      prefs['hideBlockExplorerWarning'] = _prefs.hideBlockExplorerWarning;
      prefs['nodesChosenByUser'] = _prefs.nodesChosenByUser;

      backupJson['prefs'] = prefs;

      Logging.instance.d("SWB backing up addressbook");

      final AddressBookService addressBookService = AddressBookService();
      final addresses = addressBookService.contacts;
      backupJson['addressBookEntries'] = addresses
          .map((e) => e.toMap())
          .toList();

      Logging.instance.d("SWB backing up wallets");

      final List<dynamic> backupWallets = [];
      for (final wallet in _wallets.wallets) {
        final Map<String, dynamic> backupWallet = {};
        backupWallet['name'] = wallet.info.name;
        backupWallet['id'] = wallet.walletId;
        backupWallet['isFavorite'] = wallet.info.isFavourite;
        backupWallet['favouriteOrderIndex'] = wallet.info.favouriteOrderIndex;
        backupWallet['otherDataJsonString'] = wallet.info.otherDataJsonString;

        // Masternode private keys live in secure storage, not otherData.
        if (wallet is PivxWallet) {
          final keys = <String, String>{};
          for (final mn in wallet.masternodes) {
            final key = await wallet.masternodeKey(mn);
            if (key != null) keys[mn.id] = key;
          }
          if (keys.isNotEmpty) backupWallet['pivxMasternodeKeys'] = keys;

          // Coin control: frozen, unfrozen and named coins.
          final coinFlags = await wallet.userCoinFlags();
          if (coinFlags.isNotEmpty) backupWallet['coinFlags'] = coinFlags;
        }

        if (wallet is ViewOnlyOptionInterface && wallet.isViewOnly) {
          backupWallet['viewOnlyWalletDataKey'] =
              (await wallet.getViewOnlyWalletData()).toJsonEncodedString();
        } else if (wallet is MnemonicInterface) {
          backupWallet['mnemonic'] = await wallet.getMnemonic();
          backupWallet['mnemonicPassphrase'] = await wallet
              .getMnemonicPassphrase();
        }
        backupWallet['coinName'] = wallet.info.coin.identifier;
        backupWallet['storedChainHeight'] = wallet.info.cachedChainHeight;

        // backupWallet['txidList'] = DB.instance.get<dynamic>(
        //     boxName: wallet.walletId, key: "cachedTxids") as List?;
        // the following can cause a deadlock
        // (await manager.transactionData).getAllTransactions().keys.toList();

        backupWallet['restoreHeight'] = wallet.info.restoreHeight;

        final isarNotes = await MainDB.instance.isar.transactionNotes
            .where()
            .walletIdEqualTo(wallet.walletId)
            .findAll();

        final notes = isarNotes.asMap().map(
          (key, value) => MapEntry(value.txid, value.value),
        );

        backupWallet['notes'] = notes;

        // Address labels: the user's, and masternode collateral ones.
        backupWallet['addressLabels'] = {
          for (final l
              in await MainDB.instance.isar.addressLabels
                  .where()
                  .walletIdEqualTo(wallet.walletId)
                  .findAll())
            if (l.value.isNotEmpty) l.addressString: l.value,
        };

        backupWallets.add(backupWallet);
      }
      backupJson['wallets'] = backupWallets;
    });
    Logging.instance.d("createStackWalletJSON DB.instance.mutex released");

    Logging.instance.d("...createStackWalletJSON complete");
    return backupJson;
  }

  static Future<bool> _asyncRestore(
    Tuple2<dynamic, WalletInfo> tuple,
    Prefs prefs,
    NodeService nodeService,
    SecureStorageInterface secureStorageInterface,
    StackRestoringUIState? uiState,
  ) async {
    final info = tuple.item2;
    final walletbackup = tuple.item1;

    String? mnemonic, mnemonicPassphrase;

    ViewOnlyWalletData? viewOnlyData;
    if (info.isViewOnly) {
      final viewOnlyDataEncoded =
          walletbackup['viewOnlyWalletDataKey'] as String;

      viewOnlyData = ViewOnlyWalletData.fromJsonEncodedString(
        viewOnlyDataEncoded,
        walletId: info.walletId,
      );
    } else if (walletbackup['mnemonic'] != null) {
      mnemonic = walletbackup['mnemonic'] as String;
      mnemonicPassphrase = walletbackup['mnemonicPassphrase'] as String;
    }

    uiState?.update(
      walletId: info.walletId,
      restoringStatus: StackRestoringStatus.restoring,
      mnemonic: mnemonic,
      mnemonicPassphrase: mnemonicPassphrase,
    );
    Wallet? wallet;
    bool didExit = false;
    try {
      wallet = await Wallet.create(
        walletInfo: info,
        mainDB: MainDB.instance,
        secureStorageInterface: secureStorageInterface,
        nodeService: nodeService,
        prefs: prefs,
        mnemonic: mnemonic,
        mnemonicPassphrase: mnemonicPassphrase,
        viewOnlyData: viewOnlyData,
      );

      await wallet.init();

      // Only in backups of wallets that have any.
      final masternodeKeys = Map<String, String>.from(
        walletbackup['pivxMasternodeKeys'] as Map? ?? {},
      );
      for (final e in masternodeKeys.entries) {
        await secureStorageInterface.write(
          key: pivxMasternodeKeyName(info.walletId, e.key),
          value: e.value,
        );
      }

      int restoreHeight = walletbackup['restoreHeight'] as int;
      if (restoreHeight <= 0) {
        restoreHeight = walletbackup['storedChainHeight'] as int;
      }

      final Future<void> restoringFuture = wallet.recover(isRescan: false);

      uiState?.update(
        walletId: info.walletId,
        restoringStatus: StackRestoringStatus.restoring,
        wallet: wallet,
      );

      if (_shouldCancelRestore) {
        return false;
      }

      // restore notes
      final notesMap = Map<String, String>.from(walletbackup["notes"] as Map);
      final List<TransactionNote> notes = [];

      for (final key in notesMap.keys) {
        if (notesMap[key] != null && notesMap[key]!.isNotEmpty) {
          notes.add(
            TransactionNote(
              walletId: info.walletId,
              txid: key,
              value: notesMap[key]!,
            ),
          );
        }
      }

      if (notes.isNotEmpty) {
        await MainDB.instance.isar.writeTxn(() async {
          await MainDB.instance.isar.transactionNotes.putAll(notes);
        });
      }

      for (final e in Map<String, dynamic>.from(
        walletbackup["addressLabels"] as Map,
      ).entries) {
        final value = e.value;
        if (value is! String || value.isEmpty) continue;
        final existing = MainDB.instance.getAddressLabelSync(
          info.walletId,
          e.key,
        );
        await MainDB.instance.updateAddressLabel(
          existing?.copyWith(label: value) ??
              AddressLabel(
                walletId: info.walletId,
                addressString: e.key,
                value: value,
                tags: null,
              ),
        );
      }

      if (_shouldCancelRestore) {
        return false;
      }

      try {
        // if mnemonic verified does not get set the wallet will be deleted on app restart
        await wallet.info.setMnemonicVerified(isar: MainDB.instance.isar);
      } catch (_) {
        // Do not interrupt/cancel/fail restore from swb if setMnemonicVerified was already set
      }

      if (_shouldCancelRestore) {
        return false;
      }

      await restoringFuture;

      // On the coins found by the restore. Only in backups of wallets that
      // have any.
      if (wallet is PivxWallet && walletbackup['coinFlags'] is List) {
        await wallet.restoreUserCoinFlags(walletbackup['coinFlags'] as List);
      }

      final currentAddress = await wallet.getCurrentReceivingAddress();

      await wallet.exit();
      didExit = true;

      Logging.instance.i(
        "SWB restored: ${info.walletId} ${info.name} ${info.coin.prettyName}",
      );
      uiState?.update(
        walletId: info.walletId,
        restoringStatus: StackRestoringStatus.success,
        wallet: wallet,
        address: currentAddress?.value,
        height: restoreHeight,
        mnemonic: mnemonic,
        mnemonicPassphrase: mnemonicPassphrase,
      );
    } catch (e, s) {
      Logging.instance.e(
        "${wallet?.runtimeType} _asyncRestore failed",
        error: e,
        stackTrace: s,
      );
      uiState?.update(
        walletId: info.walletId,
        restoringStatus: StackRestoringStatus.failed,
        mnemonic: mnemonic,
        mnemonicPassphrase: mnemonicPassphrase,
      );
      return false;
    } finally {
      if (!didExit) {
        await wallet?.exit();
      }
    }
    return true;
  }

  static Future<void> _restoreEverythingButWallets(
    Map<String, dynamic> validJSON,
    StackRestoringUIState? uiState,
    Map<String, String> oldToNewWalletIdMap,
    SecureStorageInterface secureStorageInterface,
  ) async {
    final Map<String, dynamic> prefs =
        validJSON["prefs"] as Map<String, dynamic>;
    final List<dynamic> addressBookEntries =
        validJSON["addressBookEntries"] as List;
    final List<dynamic> nodes = validJSON["nodes"] as List;

    uiState?.preferences = StackRestoringStatus.restoring;

    Logging.instance.d("SWB restoring prefs");
    await _restorePrefs(prefs);

    uiState?.preferences = StackRestoringStatus.success;
    uiState?.addressBook = StackRestoringStatus.restoring;

    Logging.instance.d("SWB restoring addressbook");
    await _restoreAddressBook(addressBookEntries);

    uiState?.addressBook = StackRestoringStatus.success;
    uiState?.nodes = StackRestoringStatus.restoring;

    Logging.instance.d("SWB restoring nodes");
    await _restoreNodes(nodes, secureStorageInterface);

    uiState?.nodes = StackRestoringStatus.success;
  }

  /// Returns false when the restore was cancelled.
  static Future<bool?> restoreStackWalletJSON(
    String jsonBackup,
    StackRestoringUIState? uiState,
    SecureStorageInterface secureStorageInterface,
  ) async {
    if (!Platform.isLinux) await WakelockPlus.enable();
    try {
      return await _restoreStackWalletJSON(
        jsonBackup,
        uiState,
        secureStorageInterface,
      );
    } finally {
      // Also after a cancel or an error, or the screen stays on until the
      // app is closed.
      try {
        if (!Platform.isLinux) await WakelockPlus.disable();
      } catch (e, s) {
        // Not worth failing a restore whose wallets are all in.
        Logging.instance.w("SWB restore: wakelock", error: e, stackTrace: s);
      }
    }
  }

  static Future<bool?> _restoreStackWalletJSON(
    String jsonBackup,
    StackRestoringUIState? uiState,
    SecureStorageInterface secureStorageInterface,
  ) async {
    Logging.instance.d("SWB creating temp backup");
    final preRestoreJSON = await createStackWalletJSON(
      secureStorage: secureStorageInterface,
    );
    Logging.instance.d("SWB temp backup created");

    final List<String> _currentWalletIds = await MainDB.instance.isar.walletInfo
        .where()
        .walletIdProperty()
        .findAll();

    final preRestoreState = PreRestoreState(
      _currentWalletIds.toSet(),
      preRestoreJSON,
    );

    final Map<String, String> oldToNewWalletIdMap = {};

    final Map<String, dynamic> validJSON =
        json.decode(jsonBackup) as Map<String, dynamic>;

    final List<dynamic> wallets = validJSON["wallets"] as List;

    // check for duplicate walletIds and assign new ones if required
    for (final wallet in wallets) {
      if (_currentWalletIds.contains(wallet["id"] as String)) {
        oldToNewWalletIdMap[wallet["id"] as String] = const Uuid().v1();
      } else {
        oldToNewWalletIdMap[wallet["id"] as String] = wallet["id"] as String;
      }
    }

    uiState?.decryption = StackRestoringStatus.success;

    // basic cancel check here
    // no reverting required yet as nothing has been written to store
    if (_checkShouldCancel(null, secureStorageInterface)) {
      return false;
    }

    await _restoreEverythingButWallets(
      validJSON,
      uiState,
      oldToNewWalletIdMap,
      secureStorageInterface,
    );

    // check if cancel was requested and restore previous state
    if (_checkShouldCancel(preRestoreState, secureStorageInterface)) {
      return false;
    }

    final nodeService = NodeService(
      secureStorageInterface: secureStorageInterface,
    );

    final _prefs = Prefs.instance;
    await _prefs.init();

    final List<Tuple2<dynamic, WalletInfo>> managers = [];

    final Map<String, WalletRestoreState> walletStates = {};

    // Favourites restored come after this device's, in their order.
    final favouriteOrder = swbFavouriteOrder(
      wallets,
      after:
          await MainDB.instance.isar.walletInfo
              .where()
              .sortByFavouriteOrderIndexDesc()
              .favouriteOrderIndexProperty()
              .findFirst() ??
          -1,
    );

    for (final walletbackup in wallets) {
      // check if cancel was requested and restore previous state
      if (_checkShouldCancel(preRestoreState, secureStorageInterface)) {
        return false;
      }

      final coin = AppConfig.getCryptoCurrencyFor(
        walletbackup['coinName'] as String,
      );

      if (coin == null) {
        continue;
      }

      final walletName = walletbackup['name'] as String;
      final walletId = oldToNewWalletIdMap[walletbackup["id"] as String]!;

      Map<String, dynamic>? otherData;
      try {
        if (walletbackup["otherDataJsonString"] is String) {
          final data = jsonDecode(
            walletbackup["otherDataJsonString"] as String,
          );
          otherData = Map<String, dynamic>.from(data as Map);
        }
      } catch (e, s) {
        Logging.instance.e(
          "SWB restore walletinfo otherdata error: ",
          error: e,
          stackTrace: s,
        );
      }

      final info = WalletInfo(
        coinName: coin.identifier,
        walletId: walletId,
        name: walletName,
        mainAddressType: coin.defaultAddressType,
        restoreHeight: walletbackup['restoreHeight'] as int,
        otherDataJsonString: otherData == null ? null : jsonEncode(otherData),
        cachedChainHeight: walletbackup['storedChainHeight'] as int,
        favouriteOrderIndex: favouriteOrder[walletbackup] ?? -1,
      );

      var node = nodeService.getPrimaryNodeFor(currency: coin);

      if (node == null) {
        node = coin.defaultNode(isPrimary: true);
        await nodeService.save(node, false);
      }

      // check if cancel was requested and restore previous state
      if (_checkShouldCancel(preRestoreState, secureStorageInterface)) {
        return false;
      }

      managers.add(Tuple2(walletbackup, info));
      // check if cancel was requested and restore previous state
      if (_checkShouldCancel(preRestoreState, secureStorageInterface)) {
        return false;
      }

      walletStates[walletId] = WalletRestoreState(
        coin: coin,
        restoringStatus: StackRestoringStatus.waiting,
        walletId: walletId,
        walletName: walletName,
      );
    }

    // check if cancel was requested and restore previous state
    if (_checkShouldCancel(preRestoreState, secureStorageInterface)) {
      return false;
    }

    // set the states so the ui can display each status as they update during restores
    uiState?.walletStates = walletStates;

    final List<Future<bool>> restoreStatuses = [];
    // start restoring wallets
    for (final tuple in managers) {
      // check if cancel was requested and restore previous state
      if (_checkShouldCancel(preRestoreState, secureStorageInterface)) {
        return false;
      }
      final bools = await _asyncRestore(
        tuple,
        _prefs,
        nodeService,
        secureStorageInterface,
        uiState,
      );
      restoreStatuses.add(Future(() => bools));
    }

    // check if cancel was requested and restore previous state
    if (_checkShouldCancel(preRestoreState, secureStorageInterface)) {
      return false;
    }

    for (final Future<bool> status in restoreStatuses) {
      // check if cancel was requested and restore previous state
      if (_checkShouldCancel(preRestoreState, secureStorageInterface)) {
        return false;
      }
      await status;
    }

    // check if cancel was requested and restore previous state
    if (_checkShouldCancel(preRestoreState, secureStorageInterface)) {
      return false;
    }

    Logging.instance.d("done with SWB restore");

    await Wallets.sharedInstance.loadAfterStackRestore(
      _prefs,
      uiState?.wallets ?? [],
      Util.isDesktop,
    );

    return true;
  }

  static Future<void> _revert(
    PreRestoreState revertToState,
    SecureStorageInterface secureStorageInterface,
  ) async {
    final Map<String, dynamic> prefs =
        revertToState.validJSON["prefs"] as Map<String, dynamic>;
    final List<dynamic> addressBookEntries =
        revertToState.validJSON["addressBookEntries"] as List;
    final List<dynamic> nodes = revertToState.validJSON["nodes"] as List;

    // prefs
    await _restorePrefs(prefs);

    // contacts
    final addressBookService = AddressBookService();
    final allContactIds = addressBookService.contacts.map((e) => e.customId);

    final Map<String, dynamic> preContactMap = {};
    for (final contact in addressBookEntries) {
      preContactMap[contact['id'] as String] = contact as Map<String, dynamic>;
    }
    // delete any newly added contacts while reverting previous contact data
    // on contacts that may have been modified
    for (final String id in allContactIds) {
      final contact = preContactMap[id];
      // pre restore state has contact
      if (contact != null) {
        // ensure this contact's data matches the pre restore state
        final List<ContactAddressEntry> addresses = [];
        for (final address in (contact['addresses'] as List<dynamic>)) {
          final entry = ContactAddressEntry()
            ..coinName = address['coin'] as String
            ..address = address['address'] as String;

          try {
            entry.coin;
          } catch (_) {
            // coin not supported so ignore this entry
            continue;
          }

          addresses.add(entry);
        }
        await addressBookService.editContact(
          ContactEntry(
            emojiChar: contact['emoji'] as String?,
            name: contact['name'] as String,
            addresses: addresses,
            isFavorite: contact['isFavorite'] as bool,
            customId: contact['id'] as String,
          ),
        );
      } else {
        // otherwise remove it as it was not there before attempting SWB restore
        await addressBookService.removeContact(id);
      }
    }

    // nodes
    final NodeService nodeService = NodeService(
      secureStorageInterface: secureStorageInterface,
    );
    final currentNodes = nodeService.nodes;
    final Map<String, Map<String, dynamic>> preNodeMap = {};
    for (final nodeData in nodes) {
      preNodeMap[nodeData['id'] as String] = nodeData as Map<String, dynamic>;
    }
    // delete only newly added during attempted restore
    for (final node in currentNodes) {
      final nodeData = preNodeMap[node.id];
      if (nodeData != null) {
        // node existed before restore attempt
        // revert to pre restore node
        await nodeService.save(_nodeFromBackup(nodeData), true);
      } else {
        await nodeService.delete(node.id, true);
      }
    }

    await nodeService.updateDefaults();

    // finally remove any added wallets, with their keys and data
    for (final info
        in await MainDB.instance.isar.walletInfo.where().findAll()) {
      if (!revertToState.walletIds.contains(info.walletId)) {
        await Wallets.sharedInstance.deleteWallet(info, secureStorageInterface);
      }
    }

    _cancelCompleter!.complete();
    _shouldCancelRestore = false;
    Logging.instance.d("Revert SWB complete");
  }

  static Future<void> _restorePrefs(Map<String, dynamic> prefs) async {
    final _prefs = Prefs.instance;
    await _prefs.init();
    _prefs.currency = prefs['currency'] as String;
    // A language this version doesn't have, or "": the system's.
    _prefs.language =
        Language.fromCode(prefs['language'] as String)?.code ?? "";
    _prefs.showFavoriteWallets = prefs['showFavoriteWallets'] as bool;
    _prefs.syncType = prefs['syncType'] == "currentWalletOnly"
        ? SyncingType.currentWalletOnly
        : prefs['syncType'] == "selectedWalletsAtStartup"
        ? SyncingType.selectedWalletsAtStartup
        : SyncingType.allWalletsOnStartup; //
    _prefs.walletIdsSyncOnStartup =
        (prefs['walletIdsSyncOnStartup'] as List<dynamic>)
            .map<String>((e) => e as String)
            .toList();
    _prefs.showTestNetCoins = prefs['showTestNetCoins'] as bool;
    // The PIVXie experience.
    _prefs.externalCalls = prefs['externalCalls'] as bool;
    // Auto backup stays as set up on this device: its folder and key are
    // local (the key isn't in the file), so turning it on from a backup
    // left it without a key.

    _prefs.enableCoinControl = prefs['enableCoinControl'] as bool;
    _prefs.hideBlockExplorerWarning = prefs['hideBlockExplorerWarning'] as bool;
    // For the coins this app has (the backup's may be another app's).
    final units = prefs['amountUnits'] as Map;
    for (final coin in AppConfig.coins) {
      final unit = AmountUnit.values.asNameMap()[units[coin.identifier]];
      if (unit != null && AmountUnit.valuesForCoin(coin).contains(unit)) {
        _prefs.updateAmountUnit(coin: coin, amountUnit: unit);
      }
    }
    final decimals = prefs['maxDecimals'] as Map;
    for (final coin in AppConfig.coins) {
      final n = decimals[coin.identifier];
      // Prefs' own upper bound.
      if (n is int && n >= 0 && n <= 18) {
        _prefs.updateMaxDecimals(coin: coin, maxDecimals: n);
      }
    }
    // Only themes installed here (the app's own light and dark ones).
    Future<String?> theme(String key) async {
      final id = prefs[key];
      return id is String &&
              await ThemeService.instance.verifyInstalled(themeId: id)
          ? id
          : null;
    }

    if (await theme('themeId') case final id?) _prefs.themeId = id;
    if (await theme('systemBrightnessLightThemeId') case final id?) {
      _prefs.systemBrightnessLightThemeId = id;
    }
    if (await theme('systemBrightnessDarkThemeId') case final id?) {
      _prefs.systemBrightnessDarkThemeId = id;
    }
    _prefs.enableSystemBrightness = prefs['enableSystemBrightness'] as bool;
    // Newer than the baseline: older backups don't have it.
    if (prefs['nodesChosenByUser'] case final List<dynamic> coins) {
      _prefs.nodesChosenByUser = [
        for (final coin in AppConfig.coins)
          if (coins.contains(coin.identifier)) coin.identifier,
      ];
    }
  }

  static Future<void> _restoreAddressBook(
    List<dynamic> addressBookEntries,
  ) async {
    final AddressBookService addressBookService = AddressBookService();
    for (final contact in addressBookEntries) {
      final List<ContactAddressEntry> addresses = [];
      for (final address in (contact['addresses'] as List<dynamic>)) {
        final entry = ContactAddressEntry()
          ..coinName = address['coin'] as String
          ..address = address['address'] as String;

        try {
          entry.coin;
        } catch (_) {
          // coin not supported so ignore this entry
          continue;
        }

        addresses.add(entry);
      }
      if (addresses.isNotEmpty) {
        await addressBookService.addContact(
          ContactEntry(
            emojiChar: contact['emoji'] as String?,
            name: contact['name'] as String,
            addresses: addresses,
            isFavorite: contact['isFavorite'] as bool,
            customId: contact['id'] as String,
          ),
        );
      }
    }
  }

  static Future<void> _restoreNodes(
    List<dynamic> nodes,
    SecureStorageInterface secureStorageInterface,
  ) async {
    final NodeService nodeService = NodeService(
      secureStorageInterface: secureStorageInterface,
    );
    for (final node in nodes) {
      await nodeService.save(
        _nodeFromBackup(Map<String, dynamic>.from(node as Map)),
        true,
      );
    }

    await nodeService.updateDefaults();
  }
}

/// A node as [NodeModel.toMap] wrote it into a backup.
NodeModel _nodeFromBackup(Map<String, dynamic> node) => NodeModel(
  host: node['host'] as String,
  port: node['port'] as int,
  name: node['name'] as String,
  id: node['id'] as String,
  useSSL: node['useSSL'] as bool,
  coinName: node['coinName'] as String,
  torEnabled: node['torEnabled'] as bool,
  clearnetEnabled: node['clearEnabled'] as bool,
  isPrimary: node['isPrimary'] as bool,
);

/// Favourite order for the backed up [wallets] (their JSON maps) that are
/// favourites: numbered from [after] + 1, in their order in the backup.
/// Wallets that aren't favourites aren't in the result.
Map<Object, int> swbFavouriteOrder(
  List<dynamic> wallets, {
  required int after,
}) {
  final favourites = <({int position, int order, Object wallet})>[];
  for (final (i, w) in wallets.indexed) {
    final index = (w as Map)['favouriteOrderIndex'] as int;
    if (index < 0) continue;
    favourites.add((position: i, order: index, wallet: w));
  }
  favourites.sort(
    (a, b) => a.order != b.order
        ? a.order.compareTo(b.order)
        : a.position.compareTo(b.position),
  );
  return Map.identity()..addAll({
    for (final (k, f) in favourites.indexed) f.wallet: after + 1 + k,
  });
}

/// Whether [json] (a decrypted backup) has everything restoring reads from
/// what [SWB.createStackWalletJSON] writes. Not, for example, a Stack Wallet
/// backup: the same file format, but without some of it.
bool isSwbBackup(String json) {
  final Object? backup;
  try {
    backup = jsonDecode(json);
  } on FormatException {
    return false;
  }
  bool str(Object? v) => v is String;
  bool flag(Object? v) => v is bool;
  bool number(Object? v) => v is int;
  bool map(Object? v) => v is Map;
  bool strings(Object? v) => v is List && v.every(str);
  bool has(Object? m, Map<String, bool Function(Object?)> fields) =>
      m is Map && fields.entries.every((f) => f.value(m[f.key]));
  bool all(Object? list, Map<String, bool Function(Object?)> fields) =>
      list is List && list.every((e) => has(e, fields));

  if (backup is! Map) return false;
  final wallets = backup['wallets'];
  return has(backup['prefs'], {
        'currency': str,
        'language': str,
        'showFavoriteWallets': flag,
        'syncType': str,
        'walletIdsSyncOnStartup': strings,
        'showTestNetCoins': flag,
        'externalCalls': flag,
        'enableCoinControl': flag,
        'hideBlockExplorerWarning': flag,
        'amountUnits': map,
        'maxDecimals': map,
        'themeId': str,
        'enableSystemBrightness': flag,
        'systemBrightnessLightThemeId': str,
        'systemBrightnessDarkThemeId': str,
      }) &&
      all(backup['nodes'], {
        'host': str,
        'port': number,
        'name': str,
        'id': str,
        'useSSL': flag,
        'coinName': str,
        'torEnabled': flag,
        'clearEnabled': flag,
        'isPrimary': flag,
      }) &&
      all(backup['addressBookEntries'], {
        'emoji': (v) => v == null || v is String,
        'name': str,
        'addresses': (v) => all(v, {'address': str, 'coin': str}),
        'id': str,
        'isFavorite': flag,
      }) &&
      all(wallets, {
        'name': str,
        'id': str,
        'favouriteOrderIndex': number,
        'otherDataJsonString': (v) => v == null || v is String,
        'coinName': str,
        'storedChainHeight': number,
        'restoreHeight': number,
        'notes': map,
        'addressLabels': map,
        // Only when the wallet has any.
        'pivxMasternodeKeys': (v) => v == null || v is Map,
        'coinFlags': (v) => v == null || v is List,
      }) &&
      // A view only wallet's data, or the recovery phrase.
      (wallets as List).every(
        (w) =>
            (w as Map)['viewOnlyWalletDataKey'] is String ||
            (w['mnemonic'] is String && w['mnemonicPassphrase'] is String),
      );
}
